using AcxiomCRM.Web.Data; using AcxiomCRM.Web.Models; using AcxiomCRM.Web.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize] public class DashboardController:Controller
{ private readonly CrmService _crm; private readonly ApplicationDbContext _db; public DashboardController(CrmService crm,ApplicationDbContext db){_crm=crm;_db=db;}
 public async Task<IActionResult> Index(){var uid=_db.Users.Where(u=>u.UserName==User.Identity!.Name).Select(u=>u.Id).FirstOrDefault();var roles=await GetRoles();bool priv=roles.Contains("Admin")||roles.Contains("Manager");var cs=_crm.CustomersFor(uid,priv);var ls=_crm.LeadsFor(uid,priv);var os=_crm.OpportunitiesFor(uid,priv);var vm=new DashboardVm{Customers=await cs.CountAsync(),Leads=await ls.CountAsync(),OpenLeads=await ls.CountAsync(x=>x.Status!=LeadStatus.Converted&&x.Status!=LeadStatus.Lost&&x.Status!=LeadStatus.Unqualified),Opportunities=await os.CountAsync(),Won=await os.CountAsync(x=>x.Status==OpportunityStatus.Won),Lost=await os.CountAsync(x=>x.Status==OpportunityStatus.Lost),Pipeline=await os.Where(x=>x.Status==OpportunityStatus.Open).SumAsync(x=>x.Amount*x.Probability/100m),Risky=await os.Where(x=>x.Status==OpportunityStatus.Open).OrderByDescending(x=>x.Probability).Take(6).ToListAsync()};vm.LeadStatus=await ls.GroupBy(x=>x.Status.ToString()).ToDictionaryAsync(g=>g.Key,g=>g.Count());vm.PipelineByStage=await os.Where(x=>x.Status==OpportunityStatus.Open).GroupBy(x=>x.Stage.ToString()).ToDictionaryAsync(g=>g.Key,g=>g.Sum(x=>x.Amount));return View(vm);}
 private async Task<List<string>> GetRoles(){var u=await _db.Users.FirstAsync(x=>x.UserName==User.Identity!.Name);var um=HttpContext.RequestServices.GetRequiredService<Microsoft.AspNetCore.Identity.UserManager<ApplicationUser>>();return (await um.GetRolesAsync(u)).ToList();}
}
